from io import StringIO

import pytest
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat

import test_retail_report_jwt_composition as setup

from sp001.contracts.case_access_grant_administration import (
    GrantAdministrationAction as Action, GrantAdministrationRecord,
)
from sp001.infrastructure.retail_vm_report_cli import main


@pytest.fixture(scope="module")
def signing_keys():
    # Synthetic keys are generated by tests only.
    return tuple(
        rsa.generate_private_key(public_exponent=65537, key_size=2048)
        for _ in range(2)
    )


def arguments(path, report_id="REPORT-1", audience=None):
    return [
        "--database", str(path),
        "--issuer", setup.ISSUER,
        "--audience", audience or setup.AUDIENCE,
        "--key-id", "KEY-1",
        "--public-key-env", "VM_TEST_PUBLIC_KEY",
        "--max-lifetime-seconds", "120",
        "--max-token-bytes", "16384",
        "--case-id", "CASE",
        "--report-id", report_id,
    ]


def run_cli(path, keys, credential, *, report_id="REPORT-1", audience=None, env=None):
    output = StringIO()
    errors = StringIO()
    if env is None:
        env = {"VM_TEST_PUBLIC_KEY": keys[0].public_key().public_bytes(
            Encoding.PEM, PublicFormat.SubjectPublicKeyInfo,
        ).decode("ascii")}
    code = main(
        arguments(path, report_id, audience),
        environment=env, stdin=StringIO(credential + "\n"),
        stdout=output, stderr=errors,
    )
    return code, output.getvalue(), errors.getvalue()


def test_real_signed_token_recovers_readable_declared_report(tmp_path, signing_keys):
    path, service, _, _ = setup.environment(tmp_path, signing_keys)
    credential = setup.token(signing_keys[0])
    service.save(
        credential=credential, identity=setup.IDENTITY, report=setup.make_report(),
    )
    code, output, errors = run_cli(path, signing_keys, credential)
    assert code == 0
    assert errors == ""
    assert "REPORTE DE REVISIÓN VM" in output
    assert "Atribución: DECLARADA" in output
    assert setup.make_report().evaluations[0].rationale in output
    assert credential not in output


@pytest.mark.parametrize("fault", ["signature", "audience", "oversized"])
def test_invalid_credentials_emit_no_report(tmp_path, signing_keys, fault):
    path, _, _, _ = setup.environment(tmp_path, signing_keys)
    if fault == "signature":
        credential = setup.token(signing_keys[1])
    elif fault == "audience":
        credential = setup.token(signing_keys[0], overrides={"aud": "OTHER"})
    else:
        credential = "x" * 17000
    code, output, errors = run_cli(path, signing_keys, credential)
    assert code == 3
    assert output == ""
    assert credential not in errors


def test_revocation_denies_existing_report(tmp_path, signing_keys):
    path, service, grants, definitions = setup.environment(tmp_path, signing_keys)
    credential = setup.token(signing_keys[0])
    service.save(
        credential=credential, identity=setup.IDENTITY, report=setup.make_report(),
    )
    for index, grant in enumerate(definitions):
        grants.apply(record=GrantAdministrationRecord(
            f"CLI-REVOKE-{index}", grant.principal,
            Action.REVOKE, grant, int(setup.time.time()),
        ))
    code, output, errors = run_cli(path, signing_keys, credential)
    assert code == 4
    assert output == ""
    assert "denegado" in errors


def test_authorized_absence_has_its_own_exit_code(tmp_path, signing_keys):
    path, _, _, _ = setup.environment(tmp_path, signing_keys)
    code, output, errors = run_cli(
        path, signing_keys, setup.token(signing_keys[0]), report_id="MISSING",
    )
    assert code == 5
    assert output == ""
    assert "no encontrado" in errors


def test_missing_configuration_does_not_create_database(tmp_path, signing_keys):
    path = tmp_path / "not-created.sqlite3"
    code, output, _ = run_cli(path, signing_keys, "unused", env={})
    assert code == 2
    assert output == ""
    assert not path.exists()
